// Scraper Finder starter workflow
// Edit this object for your run. The full input schema is linked in the sticky note.
const input = {
  "mode": "search",
  "startUrls": [],
  "adults": 2,
  "rooms": 1,
  "propertyType": "all",
  "minReviewScore": 0,
  "stars": "0",
  "freeCancellation": false,
  "breakfast": false,
  "pool": false,
  "currency": "USD",
  "language": "en-us",
  "maxItems": 3,
  "includeRooms": true,
  "includeFullAmenities": false
};

return [{ json: input }];

const payload = $input.first().json;
const rows = Array.isArray(payload) ? payload : (payload && (payload.items || payload.data) ? (payload.items || payload.data) : []);
const keyField = "url";
const seen = new Set();

const clean = rows
  .filter((row) => row && typeof row === 'object')
  .map((row) => {
    const out = {};
    for (const [k, v] of Object.entries(row)) {
      if (v === null || v === undefined) continue;
      out[k] = typeof v === 'string' ? v.trim() : v;
    }
    out._source = "https://apify.com/nimbryxo-studio/booking-com-hotel-price-and-amenity-search-scraper";
    out._scrapedAt = new Date().toISOString();
    return out;
  })
  .filter((row) => {
    const value = row[keyField];
    const dedupe = value === undefined || value === null || value === '' ? JSON.stringify(row) : String(value).toLowerCase();
    if (seen.has(dedupe)) return false;
    seen.add(dedupe);
    return true;
  });

return clean.map((json) => ({ json }));
